// DuckBot v2.2.3 - Enhanced News Video Generator with ComfyUI Integration
// Generates news-style videos with news anchor overlay

const prompt = $input.first().json.prompt;
const userId = $input.first().json.user_id;
const serverId = $input.first().json.server_id;
const userName = $input.first().json.user_name || 'User';
const newsType = $input.first().json.news_type || 'general'; // general, breaking, weather, sports, etc.

// Configuration
const COMFYUI_SERVER = "127.0.0.1:8188";
const CLIENT_ID = `n8n_news_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`;
const NEWS_ANCHOR_PATH = "C:/Users/Duck1/Desktop/DuckBot Parts/DuckBotAncor/DuckBotNewsAnchor1.png";

// News-specific enhancements
const NEWS_STYLES = {
    general: "professional news broadcast, clean studio lighting, newsroom background, corporate style",
    breaking: "urgent news alert, dramatic lighting, red alert graphics, serious tone",
    weather: "weather broadcast style, meteorological graphics, clear sky background",
    sports: "sports news studio, dynamic graphics, energetic atmosphere",
    tech: "technology news, futuristic background, modern digital graphics",
    finance: "financial news studio, market graphics, professional corporate setting"
};

// Enhanced ComfyUI workflow for news video generation
function createNewsVideoWorkflow(enhancedPrompt, seed, newsAnchorPath) {
    return {
        "1": {
            "inputs": {
                "ckpt_name": "flux1-schnell-fp8.safetensors"
            },
            "class_type": "CheckpointLoaderSimple",
            "_meta": {"title": "Load Checkpoint"}
        },
        "2": {
            "inputs": {
                "text": enhancedPrompt,
                "clip": ["1", 1]
            },
            "class_type": "CLIPTextEncode",
            "_meta": {"title": "CLIP Text Encode (Prompt)"}
        },
        "3": {
            "inputs": {
                "text": "text, watermark, low quality, blurry",
                "clip": ["1", 1]
            },
            "class_type": "CLIPTextEncode",
            "_meta": {"title": "CLIP Text Encode (Negative)"}
        },
        "4": {
            "inputs": {
                "width": 1920,
                "height": 1080,
                "batch_size": 1
            },
            "class_type": "EmptyLatentImage",
            "_meta": {"title": "Empty Latent Image"}
        },
        "5": {
            "inputs": {
                "seed": seed,
                "steps": 4,
                "cfg": 1.0,
                "sampler_name": "euler",
                "scheduler": "simple",
                "denoise": 1.0,
                "model": ["1", 0],
                "positive": ["2", 0],
                "negative": ["3", 0],
                "latent_image": ["4", 0]
            },
            "class_type": "KSampler",
            "_meta": {"title": "KSampler"}
        },
        "6": {
            "inputs": {
                "samples": ["5", 0],
                "vae": ["1", 2]
            },
            "class_type": "VAEDecode",
            "_meta": {"title": "VAE Decode"}
        },
        "7": {
            "inputs": {
                "image": newsAnchorPath,
                "upload": "image"
            },
            "class_type": "LoadImage",
            "_meta": {"title": "Load News Anchor"}
        },
        "8": {
            "inputs": {
                "image1": ["6", 0],
                "image2": ["7", 0],
                "blend_mode": "overlay",
                "opacity": 0.8
            },
            "class_type": "ImageBlend",
            "_meta": {"title": "Blend News Anchor"}
        },
        "9": {
            "inputs": {
                "filename_prefix": "NewsVideo",
                "images": ["8", 0]
            },
            "class_type": "SaveImage",
            "_meta": {"title": "Save News Image"}
        },
        "10": {
            "inputs": {
                "frame_rate": 24,
                "loop_count": 0,
                "filename_prefix": "NewsVideo",
                "format": "video/mp4",
                "images": ["8", 0]
            },
            "class_type": "SaveAnimatedWEBP",
            "_meta": {"title": "Save News Video"}
        }
    };
}

// Enhanced prompt for news content
function enhanceNewsPrompt(basePrompt, newsType) {
    const newsStyle = NEWS_STYLES[newsType] || NEWS_STYLES.general;
    const baseEnhancements = [
        "4K resolution",
        "professional broadcast quality",
        "news studio setting",
        "HD video"
    ];

    return `${basePrompt}, ${newsStyle}, ${baseEnhancements.join(", ")}`;
}

// Generate random seed
function generateSeed() {
    return Math.floor(Math.random() * 2147483647);
}

// Queue prompt to ComfyUI with enhanced error handling
async function queuePromptToComfyUI(workflow) {
    try {
        const payload = {
            prompt: workflow,
            client_id: CLIENT_ID
        };

        console.log(`🔄 Connecting to ComfyUI at http://${COMFYUI_SERVER}/prompt`);

        const response = await $http.request({
            method: 'POST',
            url: `http://${COMFYUI_SERVER}/prompt`,
            headers: {
                'Content-Type': 'application/json'
            },
            data: payload,
            timeout: 600000 // 10 minutes
        });

        if (response.status === 200 && response.data) {
            console.log(`✅ Successfully queued to ComfyUI:`, response.data);
            return response.data;
        } else {
            throw new Error(`Unexpected response: ${response.status}`);
        }

    } catch (error) {
        console.error('❌ Error connecting to ComfyUI:', error.message);
        if (error.response) {
            console.error('ComfyUI Response:', error.response.status, error.response.data);
        }
        throw error;
    }
}

// Check ComfyUI status
async function checkComfyUIStatus() {
    try {
        const response = await $http.request({
            method: 'GET',
            url: `http://${COMFYUI_SERVER}/system_stats`,
            timeout: 5000
        });

        return response.status === 200;
    } catch (error) {
        console.log('⚠️ ComfyUI not responding:', error.message);
        return false;
    }
}

// Monitor generation progress
async function monitorGeneration(promptId, maxWaitTime = 300000) {
    const checkInterval = 5000; // 5 seconds
    let elapsedTime = 0;

    while (elapsedTime < maxWaitTime) {
        try {
            const historyResponse = await $http.request({
                method: 'GET',
                url: `http://${COMFYUI_SERVER}/history/${promptId}`,
                timeout: 10000
            });

            const history = historyResponse.data;
            if (history && history[promptId]) {
                const generation = history[promptId];

                if (generation.status && generation.status.completed) {
                    console.log(`✅ Generation completed after ${elapsedTime/1000}s`);
                    return {
                        success: true,
                        outputs: generation.outputs,
                        generation_time: elapsedTime / 1000
                    };
                }

                if (generation.status && generation.status.status_str) {
                    console.log(`⏳ Status: ${generation.status.status_str}`);
                }
            }

            await new Promise(resolve => setTimeout(resolve, checkInterval));
            elapsedTime += checkInterval;

        } catch (error) {
            console.error('Error checking generation status:', error.message);
            await new Promise(resolve => setTimeout(resolve, checkInterval));
            elapsedTime += checkInterval;
        }
    }

    return {
        success: false,
        error: 'Generation timed out',
        elapsed_time: elapsedTime / 1000
    };
}

// Download generated files
async function downloadGeneratedFiles(outputs) {
    const files = [];

    for (const nodeId in outputs) {
        const nodeOutput = outputs[nodeId];

        // Handle images
        if (nodeOutput.images) {
            for (const img of nodeOutput.images) {
                try {
                    const params = new URLSearchParams({
                        filename: img.filename,
                        subfolder: img.subfolder || '',
                        type: img.type || 'output'
                    });

                    const fileResponse = await $http.request({
                        method: 'GET',
                        url: `http://${COMFYUI_SERVER}/view?${params}`,
                        responseType: 'arraybuffer',
                        timeout: 60000
                    });

                    files.push({
                        type: 'image',
                        data: fileResponse.data,
                        filename: img.filename,
                        nodeId: nodeId
                    });

                } catch (error) {
                    console.error(`Error downloading image ${img.filename}:`, error.message);
                }
            }
        }

        // Handle videos/gifs
        if (nodeOutput.gifs) {
            for (const video of nodeOutput.gifs) {
                try {
                    const params = new URLSearchParams({
                        filename: video.filename,
                        subfolder: video.subfolder || '',
                        type: video.type || 'output'
                    });

                    const fileResponse = await $http.request({
                        method: 'GET',
                        url: `http://${COMFYUI_SERVER}/view?${params}`,
                        responseType: 'arraybuffer',
                        timeout: 120000
                    });

                    files.push({
                        type: 'video',
                        data: fileResponse.data,
                        filename: video.filename,
                        nodeId: nodeId
                    });

                } catch (error) {
                    console.error(`Error downloading video ${video.filename}:`, error.message);
                }
            }
        }
    }

    return files;
}

// Main news video generation function
async function generateNewsVideo(prompt, newsType) {
    try {
        console.log(`📺 Starting news video generation: "${prompt}"`);
        console.log(`📰 News type: ${newsType}`);

        // Check if ComfyUI is available
        const comfyUIAvailable = await checkComfyUIStatus();
        if (!comfyUIAvailable) {
            return {
                success: false,
                error: "ComfyUI server is not available. Please ensure ComfyUI is running on 127.0.0.1:8188",
                troubleshooting: [
                    "Start ComfyUI server",
                    "Check if port 8188 is available",
                    "Verify ComfyUI models are loaded"
                ]
            };
        }

        // Enhance the prompt for news content
        const enhancedPrompt = enhanceNewsPrompt(prompt, newsType);
        const seed = generateSeed();

        console.log(`🎯 Enhanced prompt: ${enhancedPrompt}`);
        console.log(`🎲 Using seed: ${seed}`);

        // Create the ComfyUI workflow
        const workflow = createNewsVideoWorkflow(enhancedPrompt, seed, NEWS_ANCHOR_PATH);

        // Queue the generation
        const queueResponse = await queuePromptToComfyUI(workflow);

        if (!queueResponse || !queueResponse.prompt_id) {
            return {
                success: false,
                error: "Failed to queue generation to ComfyUI",
                queue_response: queueResponse
            };
        }

        const promptId = queueResponse.prompt_id;
        console.log(`📋 Generation queued with ID: ${promptId}`);

        // Monitor the generation
        const generationResult = await monitorGeneration(promptId);

        if (!generationResult.success) {
            return {
                success: false,
                error: generationResult.error,
                prompt_id: promptId,
                elapsed_time: generationResult.elapsed_time
            };
        }

        // Download the generated files
        const files = await downloadGeneratedFiles(generationResult.outputs);

        if (files.length === 0) {
            return {
                success: false,
                error: "No files were generated",
                prompt_id: promptId,
                outputs: generationResult.outputs
            };
        }

        console.log(`✅ Successfully generated ${files.length} files`);

        return {
            success: true,
            prompt_id: promptId,
            enhanced_prompt: enhancedPrompt,
            seed: seed,
            news_type: newsType,
            files: files,
            generation_time: generationResult.generation_time,
            news_anchor_used: NEWS_ANCHOR_PATH,
            // Include file data for Discord upload
            video_files: files.filter(f => f.type === 'video'),
            image_files: files.filter(f => f.type === 'image'),
            total_files: files.length
        };

    } catch (error) {
        console.error('❌ Error in news video generation:', error.message);
        return {
            success: false,
            error: error.message,
            stack: error.stack
        };
    }
}

// Main execution
async function main() {
    try {
        if (!prompt) {
            return {
                success: false,
                error: "Please provide a prompt for news video generation",
                example: "Breaking: New AI technology revolutionizes video creation"
            };
        }

        const result = await generateNewsVideo(prompt, newsType);

        return {
            ...result,
            user_id: userId,
            server_id: serverId,
            user_name: userName,
            original_prompt: prompt,
            timestamp: new Date().toISOString(),
            comfyui_server: COMFYUI_SERVER,
            client_id: CLIENT_ID
        };

    } catch (error) {
        console.error('❌ Error in main execution:', error.message);
        return {
            success: false,
            error: error.message,
            user_id: userId,
            server_id: serverId
        };
    }
}

// Execute and return result
return await main();

// DuckBot v2.2.3 - News Video Response Formatter
// Formats news video generation responses for Discord

const input = $input.first().json;
const success = input.success;
const command = 'generate_news_video';

// Discord formatting utilities
function formatDiscordEmbed(title, description, color = 0x00ff00, fields = [], footer = null) {
    const embed = {
        title: title,
        description: description,
        color: color,
        timestamp: new Date().toISOString()
    };

    if (fields.length > 0) {
        embed.fields = fields;
    }

    if (footer) {
        embed.footer = { text: footer };
    }

    return { embeds: [embed] };
}

function formatError(error, troubleshooting = []) {
    let description = `❌ **Error:** ${error}`;

    if (troubleshooting.length > 0) {
        description += `\n\n**Troubleshooting:**\n${troubleshooting.map(tip => `• ${tip}`).join('\n')}`;
    }

    return formatDiscordEmbed(
        "🚨 News Video Generation Failed",
        description,
        0xff0000, // Red
        [],
        "DuckBot v2.2.3 - Enhanced News Generator"
    );
}

function formatSuccess() {
    const fields = [
        { name: "📺 News Type", value: input.news_type || 'general', inline: true },
        { name: "🎲 Seed", value: input.seed?.toString() || 'N/A', inline: true },
        { name: "⏱️ Generation Time", value: `${input.generation_time || 0}s`, inline: true }
    ];

    if (input.files && input.files.length > 0) {
        fields.push({
            name: "📁 Files Generated",
            value: `${input.files.length} files (${input.files.filter(f => f.type === 'image').length} images, ${input.files.filter(f => f.type === 'video').length} videos)`,
            inline: false
        });
    }

    let description = `**Original Prompt:** ${input.original_prompt}\n\n`;
    description += `**Enhanced Prompt:** ${input.enhanced_prompt}\n\n`;

    if (input.news_anchor_used) {
        description += `🎭 **News Anchor:** DuckBot News Anchor 1\n`;
    }

    description += `🔗 **Prompt ID:** \`${input.prompt_id}\``;

    return formatDiscordEmbed(
        "📺 News Video Generated Successfully!",
        description,
        0x00ff00, // Green
        fields,
        "DuckBot v2.2.3 - Enhanced News Generator with ComfyUI"
    );
}

// Format response based on success/failure
function formatResponse() {
    if (!success) {
        return formatError(
            input.error || 'Unknown error occurred',
            input.troubleshooting || []
        );
    }

    return formatSuccess();
}

// Generate response with file attachments if available
function generateResponse() {
    const discordResponse = formatResponse();

    // If we have files, we could potentially attach them
    // In a real n8n setup, you'd handle file uploads here
    if (success && input.files && input.files.length > 0) {
        // Add information about available files
        discordResponse.content = "📁 Generated files are available for download from ComfyUI output folder.";
    }

    return {
        discord_response: discordResponse,
        original_input: input,
        formatted_at: new Date().toISOString(),
        success: success,
        file_count: input.files ? input.files.length : 0,
        has_video: input.files ? input.files.some(f => f.type === 'video') : false,
        has_images: input.files ? input.files.some(f => f.type === 'image') : false
    };
}

// Execute formatting
return generateResponse();

// DuckBot v2.2.3 - Fallback Handler for Non-News Commands
// Handles other commands or provides guidance

const input = $input.first().json;
const command = input.command;
const user_name = input.user_name || 'User';

// Available commands in this enhanced workflow
const AVAILABLE_COMMANDS = [
    {
        name: "generate_news_video",
        description: "Generate professional news-style videos with news anchor overlay",
        example: "/generate_news_video Breaking: Revolutionary AI breakthrough changes everything!",
        parameters: [
            "prompt (required) - The news content to generate",
            "news_type (optional) - general, breaking, weather, sports, tech, finance"
        ]
    }
];

function formatCommandHelp() {
    const embed = {
        title: "🤖 DuckBot Enhanced News Generator",
        description: "This workflow specializes in generating professional news videos with news anchor integration.",
        color: 0x3498db,
        fields: [],
        timestamp: new Date().toISOString(),
        footer: { text: "DuckBot v2.2.3 - Enhanced News Generator" }
    };

    AVAILABLE_COMMANDS.forEach(cmd => {
        embed.fields.push({
            name: `📺 \`${cmd.name}\``,
            value: `${cmd.description}\n\n**Example:** \`${cmd.example}\`\n\n**Parameters:**\n${cmd.parameters.map(p => `• ${p}`).join('\n')}`,
            inline: false
        });
    });

    // Add ComfyUI requirements
    embed.fields.push({
        name: "🔧 Requirements",
        value: "• ComfyUI server running on 127.0.0.1:8188\n• FLUX.1 Schnell model loaded\n• News anchor image available\n• Sufficient GPU memory",
        inline: false
    });

    return { embeds: [embed] };
}

function formatUnknownCommand() {
    return {
        embeds: [{
            title: "❓ Unknown Command",
            description: `Sorry ${user_name}, I don't recognize the command \"${command}\".\n\nThis enhanced workflow currently supports news video generation. Use the webhook without a command parameter for help.`,
            color: 0xf39c12,
            timestamp: new Date().toISOString(),
            footer: { text: "DuckBot v2.2.3 - Enhanced News Generator" }
        }]
    };
}

// Main logic
function generateFallbackResponse() {
    if (!command) {
        // No command provided - show help
        return {
            discord_response: formatCommandHelp(),
            response_type: "help",
            timestamp: new Date().toISOString()
        };
    } else {
        // Unknown command
        return {
            discord_response: formatUnknownCommand(),
            response_type: "unknown_command",
            provided_command: command,
            timestamp: new Date().toISOString()
        };
    }
}

// Execute and return
return generateFallbackResponse();
